<template><section class="v2-page therapist-v2-page"><header class="v2-page-header"><p class="v2-context">患者</p><h1>患者工作区</h1><p>从当前目标、训练方案和近期变化进入，不从内部算法模块进入。</p></header><div v-if="loading" class="v2-state">正在读取患者列表…</div><div v-else-if="error" class="v2-state v2-state-error">{{ error }}</div><div v-else class="patient-directory"><RouterLink v-for="item in patients" :key="item.user_id" :to="`/therapist/patients/${item.user_id}`"><span class="patient-avatar">{{ item.username.slice(0,1) }}</span><div><strong>{{ item.username }}</strong><small>查看目标、正式训练方案与近期变化</small></div><ChevronRight aria-hidden="true"/></RouterLink></div></section></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { ChevronRight } from 'lucide-vue-next';import { therapistApi } from '@/api/therapist';import type { TherapistPatient } from '@/types/api';import { toUserMessage } from '@/utils/errors';const patients=ref<TherapistPatient[]>([]);const loading=ref(true);const error=ref('');onMounted(async()=>{try{patients.value=await therapistApi.patients()}catch(err){error.value=toUserMessage(err,'患者列表加载失败。')}finally{loading.value=false}});</script>
